/* 19. Scorecards */
function scoreW(el,title,k,items){el.innerHTML=head(k,title)+'<div class="w-grid">'+items.map(function(it,i){return rng('s'+i,it[0]+' <span class="muted">(w '+it[1]+')</span>',0,5,1,3,'')}).join('')+'</div><div class="w-out">'+kpi('Weighted score','sc','hi')+kpi('Verdict','vd')+'</div><div class="meter"><i id="mtr"></i></div>';
  bind(el,function(){var v=vals(el);var s=0,w=0;items.forEach(function(it,i){s+=v['s'+i]*it[1];w+=it[1]*5});var p=s/w*100;setK(el,'sc',fmt(p)+'/100');setK(el,'vd',p>70?'Strong':p>50?'Acceptable':p>35?'Discount heavily':'Avoid',p>50?'good':p>35?'':'bad');el.querySelector('#mtr').style.width=p+'%'})}
W.scorecard=function(el){scoreW(el,'Jurisdiction scorecard','Interactive · Module 21',[['Fiscal stability (royalty/tax changes)',3],['Permitting speed & clarity',3],['Security of tenure / rule of law',3],['Infrastructure (power, water, port)',2],['Community & Indigenous engagement',2],['Political/sovereign risk',3]])};
