/* 23. Weathering profile */
W.weathering=function(el){
  var L=[['Transported cover',26,'#b89a6a','Sand, clay and gravel deposited on top of the weathered rock. It can hide outcrops completely. Hemi sat under about 30 m of cover, which is why it was missed for decades.'],['Lateritic / ferruginous zone',28,'#a5532e','An iron-rich crust. Gold and nickel can be enriched here (laterite nickel is mined from this zone). Soil geochemistry mostly samples this.'],['Saprolite (clay)',70,'#c98a55','Completely weathered "rotten rock". It is soft (cheap to mine, free-dig) and oxide ore here is cheap to process, but leaching can deplete or enrich metal.'],['Saprock / transition',40,'#8d6b4f','Partly weathered. Recoveries and hardness change here, so the metallurgy must be tested separately.'],['Fresh rock (primary)',80,'#4b4e57','Unweathered. It is hard, costs more to mine and grind, and sulphide ore here may be refractory. Most of the long-life ore sits here.']];
  el.innerHTML=head('Interactive · Module 4','Weathering profile explorer','Click a layer')+'<div class="w-grid" style="grid-template-columns:minmax(220px,300px) 1fr;align-items:start"><svg class="w-svg" viewBox="0 0 300 260"></svg><div class="lass-info" id="wi"><b>Click a layer</b> to see why it matters for exploration and for processing costs.</div></div>';
  var svg=el.querySelector('svg'),y=10,h='';L.forEach(function(l,i){h+='<rect data-i="'+i+'" x="10" y="'+y+'" width="280" height="'+(l[1]*0.9)+'" fill="'+l[2]+'" style="cursor:pointer" stroke="rgba(0,0,0,.25)"/><text x="20" y="'+(y+l[1]*0.45+4)+'" fill="#fff" font-size="12" font-family="Inter" style="pointer-events:none">'+l[0]+'</text>';y+=l[1]*0.9});svg.innerHTML=h;
  svg.querySelectorAll('rect').forEach(function(r){r.onclick=function(){var l=L[+r.dataset.i];el.querySelector('#wi').innerHTML='<b>'+l[0]+'</b><br>'+l[3];svg.querySelectorAll('rect').forEach(function(x){x.setAttribute('stroke-width',1)});r.setAttribute('stroke-width',4)}});
};

/* 24. Flowsheet */
W.flowsheet=function(el){
  // step: [name, what it does, investor tell]
  var R={
   gold:['Free-milling gold',[['ROM ore','Run-of-mine ore arrives from the pit or stope.','Grade control here decides whether the head grade matches the reserve.'],['Crush','Jaw and cone crushers reduce rock to mill feed.','Hard ore = more energy and slower throughput.'],['SAG/ball mill','Grinding liberates gold particles. Usually the single biggest power user.','Throughput (Mtpa) is the number to watch in ramp-up quarterlies.'],['Gravity','Captures coarse free gold early, before leaching.','High gravity recovery smooths the nugget effect.'],['CIL/CIP leach','Cyanide dissolves gold, which adsorbs onto activated carbon.','Recovery is typically 90%+ for free-milling ore. Watch for recovery misses.'],['Elution','Gold is stripped back off the loaded carbon.','Rarely a bottleneck; carbon management matters.'],['Electrowinning','Gold is plated out of solution onto cathodes.','Gold in circuit can make one quarter look weak and the next look strong.'],['Doré bar','Smelted on site into doré, then refined (e.g. Perth Mint).','Payable ≈ 99.9% of contained gold. Simple, fast cash.']],'Simple and cheap. Recoveries are typically above 90%, and the product is sold almost immediately.'],
   refr:['Refractory gold',[['Ore','Gold sits inside sulphide minerals (pyrite, arsenopyrite).','Testwork must prove where the gold sits before any study is credible.'],['Crush & grind','As for free-milling ore, often finer.','Finer grinding = more power.'],['Flotation','Concentrates the gold-bearing sulphides into a small mass.','Float recovery caps total recovery.'],['POX / BIOX / roast','Oxidises the sulphides to unlock the gold. Pressure oxidation (POX) uses an autoclave.','The big capex and execution-risk step. Hemi\'s DFS included a POX circuit for its sulphide ore.'],['CIL','Leaches the oxidised concentrate.','Combined recovery is often 85–95% only if oxidation works.'],['Doré','Refined as normal.','Ramp-up risk sits in the oxidation step, not here.']],'The extra oxidation step adds capex and opex, and is a classic source of ramp-up trouble.'],
   cu:['Copper sulphide',[['Ore','Chalcopyrite or other sulphide ore, often under 1% Cu.','Small grade changes swing revenue per tonne a lot.'],['Crush','Primary crushing.','Big tonnages: throughput is everything.'],['Grind','Grinding for liberation.','Power cost is a key opex line.'],['Flotation','Floats copper minerals into a concentrate of ~25–30% Cu.','Recovery and concentrate grade both drive payable metal.'],['Thicken/filter','Dewaters concentrate for transport.','Moisture limits matter for shipping.'],['Concentrate','Shipped to a third-party smelter.','Deleterious elements (e.g. arsenic) can attract penalties.'],['Smelter (third party)','The smelter pays for payable metal minus TC/RC.','TC/RC terms, payability and penalties: see the NSR tool.']],'The miner sells concentrate and is paid for payable metal, less TC/RC and freight.'],
   cuox:['Copper oxide',[['Ore','Oxidised copper ore near surface.','Oxide caps are often small; what is underneath may be sulphide.'],['Crush','Crushed for heap stacking.','Particle size controls leach kinetics.'],['Heap leach','Acid percolates through the heap and dissolves copper.','Acid cost and supply matter; recovery is slower and lower than flotation.'],['SX','Solvent extraction concentrates and purifies the solution.','Low opex once running.'],['EW','Electrowinning plates out pure copper.','Power-intensive.'],['Cathode','LME-grade cathode sold directly.','No smelter terms, so the realised price is close to LME.']],'Makes LME-grade cathode on site with no smelter terms. Needs oxide ore and acid.'],
   li:['Spodumene',[['Ore','Pegmatite containing spodumene, typically ~1–1.5% Li₂O.','Grade and mineralogy drive recovery.'],['Crush','Crushed to feed DMS.','Simple, low cost.'],['DMS','Dense-media separation floats off light waste and keeps heavy spodumene.','Coarse recoveries are often only 60–70%.'],['Flotation (fines)','Recovers spodumene from finer material.','Adds recovery but also complexity.'],['SC5.5–6 concentrate','Spodumene concentrate (SC6 = 6% Li₂O).','Priced off SC6; lower grades are discounted.'],['Converter (China/WA)','A chemical plant converts concentrate into lithium chemicals.','Downstream conversion has been an execution graveyard (see Kwinana and Kemerton).'],['Hydroxide/carbonate','Battery-grade chemicals.','Chemical prices and concentrate prices can diverge.']],'Most Australian producers sell concentrate. Converting it to chemicals adds margin but carries big execution risk.']};
  el.innerHTML=head('Interactive · Module 8','Processing flowsheet explorer','Tap any step')+'<div class="w-tabs" role="tablist">'+Object.keys(R).map(function(k,i){return '<button role="tab" data-f="'+k+'" class="'+(i?'':'on')+'" aria-selected="'+(i?'false':'true')+'">'+R[k][0]+'</button>'}).join('')+'</div><div class="flow" id="fl"></div><div class="finfo" id="fi" aria-live="polite"></div><p class="w-note" id="fn"></p>';
  var cur='gold';
  function info(i){var s=R[cur][1][i];el.querySelectorAll('.fnode').forEach(function(b,j){b.classList.toggle('on',j===i);b.setAttribute('aria-pressed',j===i?'true':'false')});el.querySelector('#fi').innerHTML='<b>'+s[0]+'</b><dl><dt>What it does</dt><dd>'+s[1]+'</dd><dt>Investor tell</dt><dd>'+s[2]+'</dd></dl>'}
  function sh(k){cur=k;var r=R[k];el.querySelector('#fl').innerHTML=r[1].map(function(s,i){return '<button type="button" class="fnode" data-i="'+i+'" aria-pressed="false">'+s[0]+'</button>'+(i<r[1].length-1?'<span class="arr" aria-hidden="true">→</span>':'')}).join('');el.querySelector('#fn').textContent=r[2];el.querySelectorAll('.fnode').forEach(function(b){b.onclick=function(){info(+b.dataset.i)}});info(0)}
  el.querySelectorAll('[data-f]').forEach(function(b){b.onclick=function(){el.querySelectorAll('[data-f]').forEach(function(x){x.classList.remove('on');x.setAttribute('aria-selected','false')});b.classList.add('on');b.setAttribute('aria-selected','true');sh(b.dataset.f)}});sh('gold');
};

