  el.innerHTML=head('Your turn · Module 5','Spot 5 problems in a doctored release','Tap every phrase you think is a problem, then check')+'<div class="spot" role="group" aria-label="Fictional drill release">'+S.map(function(s,i){return s[1]<0?s[0]:'<span class="s" tabindex="0" role="button" aria-pressed="false" data-i="'+i+'">'+s[0]+'</span>'}).join('')+'</div><div class="row" style="display:flex;gap:10px;margin-top:12px;flex-wrap:wrap;align-items:center"><button class="btn tiny primary" data-chk>Check my picks</button><button class="btn tiny ghost" data-rev>Show the answers</button><span data-sc aria-live="polite" style="font-weight:600"></span></div><div data-out></div><p class="w-note">A fictional release. Five distinct problems; some appear in two places. Bonus: there is also something <em>missing</em>.</p>';
  function tog(n){var on=!n.classList.contains('hit');n.classList.toggle('hit',on);n.setAttribute('aria-pressed',on?'true':'false')}
  el.querySelectorAll('.s').forEach(function(n){n.onclick=function(){tog(n)};n.onkeydown=function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();tog(n)}}});
  function report(reveal){var found={},fp=[];el.querySelectorAll('.s').forEach(function(n){var s=S[+n.dataset.i];n.classList.remove('miss','reveal');if(n.classList.contains('hit')){if(s[1]>0)found[s[1]]=1;else{fp.push(s);n.classList.add('miss')}}else if(reveal&&s[1]>0)n.classList.add('reveal')});var k=Object.keys(found).length;
    el.querySelector('[data-sc]').textContent=k+' of 5 problems found'+(fp.length?' · '+fp.length+' false alarm'+(fp.length>1?'s':''):'');
    var h='<ul class="spot-list">';for(var i=1;i<=5;i++){if(found[i]||reveal)h+='<li>'+(found[i]?'✓ ':'○ ')+'<b>'+P[i]+'</b></li>'}fp.forEach(function(s){h+='<li>✗ “'+s[0].replace(/[“”]/g,'')+'”: '+s[2]+'</li>'});if(reveal||k===5)h+='<li><b>Bonus (missing):</b> no QA/QC or top-cut disclosure, and no “from” depth.</li>';el.querySelector('[data-out]').innerHTML=h+'</ul>'}
