  var STEPS=[{k:[0],h:'Early February 2020',b:'De Grey is a small explorer trading around <b>4.6c</b> (implied from the next day\'s move). Aircore drilling through transported cover near Port Hedland is about to report.'},{k:[0,1],h:'6 February 2020: discovery',b:'The Hemi release sends the stock up <b>115% intraday to 9.9c</b>. Most discovery spikes fade (Module 2). This one did not, but you could not know that on the day.'},{k:[0,1],gap:1,h:'2020–2024: building the deposit',b:'Resource growth, a DFS in September 2023 and repeated capital raisings. We do not plot prices for this period because we have not verified them: the dashed line is a gap, not a price path.'},{k:[0,1,2],gap:1,h:'29 November 2024',b:'Last close before the takeover approach: <b>A$1.52</b>.'},{k:[0,1,2,3,4],gap:1,h:'2 December 2024: Northern Star bids',b:'An all-scrip offer worth about <b>A$2.08</b> per share (≈A$5 bn). De Grey closes at <b>A$1.97</b>, a little below the offer value, the usual gap for deal risk and time. The deal completed on 5 May 2025.'},{k:[0,1,2,3,4],gap:1,all:1,h:'The whole arc',b:'About <b>45×</b> from the pre-discovery price to the offer value, in under five years. The rest of this guide is about judging, at each step, what was already priced in.'}];
