function moveSVG(mv){if(!mv)return '';var vs=[];mv.pts.forEach(function(p){if(Array.isArray(p[1]))vs.push(p[1][0],p[1][1]);else vs.push(p[1])});if(mv.ref)vs.push(mv.ref[1]);var mx=Math.max.apply(null,vs)*1.12,mn=0,b=150,H=120,h='',n=mv.pts.length,X=function(i){return 90+i*(420/Math.max(1,n-1))},Y=function(v){return b-(v-mn)/(mx-mn)*H};
  if(mv.ref){var ry=Y(mv.ref[1]);h+='<line x1="60" x2="600" y1="'+ry+'" y2="'+ry+'" stroke="'+PAL[3]+'" stroke-dasharray="6 4" stroke-width="1.5"/>'+svgText(600,ry-5,mv.ref[0]+' '+(mv.u==='A$'&&mv.ref[1]<1?Math.round(mv.ref[1]*100)+'c':(mv.u==='idx'||mv.u==='%'||mv.u==='kt'?'':mv.u)+mv.ref[1]),{a:'end',s:11,c:PAL[3],w:700})}
  var prev=null;mv.pts.forEach(function(p,i){var x=X(i),v=Array.isArray(p[1])?(p[1][0]+p[1][1])/2:p[1],y=Y(v);if(prev)h+='<line x1="'+prev[0]+'" y1="'+prev[1]+'" x2="'+x+'" y2="'+y+'" stroke="'+css('--ink2')+'" stroke-width="1.5" stroke-dasharray="'+(p[3]?'4 4':'0')+'"/>';if(Array.isArray(p[1]))h+='<rect x="'+(x-7)+'" y="'+Y(p[1][1])+'" width="14" height="'+(Y(p[1][0])-Y(p[1][1]))+'" rx="4" fill="'+PAL[0]+'"/>';else h+='<circle cx="'+x+'" cy="'+y+'" r="6" fill="'+(p[3]?css('--bg2'):PAL[0])+'" stroke="'+PAL[0]+'" stroke-width="2"/>';h+=svgText(x+(i?12:-12),y+4,p[2],{a:i?'start':'end',s:12,w:700,c:css('--ink'),mono:1})+svgText(x,b+22,p[0],{a:'middle',s:10.5});prev=[x,y]});
  return '<svg class="w-svg g-move" viewBox="0 0 640 185" role="img" aria-label="Verified before and after values">'+h+'</svg><p class="g-src">'+(mv.u==='idx'?'Indexed to 100 before the event (percentage move verified; absolute prices not shown). ':'')+'Only verified points are plotted'+(mv.pts.some(function(p){return p[3]})?'; hollow points are derived from a verified percentage move':'')+'. The line joins two points; it is not a price path.'+(mv.note?' '+mv.note:'')+'</p>'}
function calibSVG(hist){var bins=[[.3,.5],[.5,.7],[.7,.9],[.9,1.0001]];var h='',X=function(p){return 60+p*520},Y=function(p){return 220-p*190};
  h+='<line x1="'+X(0)+'" y1="'+Y(0)+'" x2="'+X(1)+'" y2="'+Y(1)+'" stroke="'+css('--ink2')+'" stroke-dasharray="5 4"/>'+svgText(X(.98),Y(1)+16,'perfect calibration',{a:'end',s:10});
  [0,.25,.5,.75,1].forEach(function(t){h+=svgText(X(t),240,Math.round(t*100)+'%',{a:'middle',s:10,mono:1})+svgText(52,Y(t)+4,Math.round(t*100)+'%',{a:'end',s:10,mono:1})});
  bins.forEach(function(b){var xs=hist.filter(function(r){return r.c>=b[0]&&r.c<b[1]});if(!xs.length)return;var mc=xs.reduce(function(a,r){return a+r.c},0)/xs.length,hr=xs.filter(function(r){return r.ok}).length/xs.length;h+='<circle cx="'+X(mc)+'" cy="'+Y(hr)+'" r="'+(5+Math.min(10,xs.length*1.5))+'" fill="'+alpha(PAL[0],.75)+'" stroke="'+PAL[0]+'"/>'+svgText(X(mc)+14,Y(hr)-8,xs.length+' call'+(xs.length>1?'s':''),{s:10})});
  h+=svgText(320,262,'Your stated confidence',{a:'middle',s:11})+'<text x="16" y="120" font-size="11" fill="'+css('--ink2')+'" font-family="Inter" transform="rotate(-90 16 120)" text-anchor="middle">How often you were right</text>';
  return '<svg class="w-svg calib" viewBox="0 0 640 270" role="img" aria-label="Calibration plot: stated confidence against hit rate">'+h+'</svg>'}
function brier(p,a,n){var s=0;for(var i=0;i<n;i++){var y=i===a?1:0;var pi=i===p.i?p.c:(1-p.c)/(n-1);s+=(pi-y)*(pi-y)}return s}
function roundHTML(r,i){return '<div class="game-card"><div class="w-k">Round '+(i+1)+' · '+r.date+(r.kind==='f'?' · fundamentals':' · market reaction')+'</div><h4>'+r.co+'</h4><p>'+r.setup+'</p><div class="game-opts">'+r.opts.map(function(o,j){return '<button class="gopt" data-j="'+j+'">'+o+'</button>'}).join('')+'</div><div class="w-ctrl" style="margin-top:12px"><label for="gconf'+i+'">Confidence in your pick <span class="v" data-v="conf"></span></label><input id="gconf'+i+'" type="range" name="conf" min="30" max="99" value="60" data-unit="%"></div><button class="btn" data-go disabled>Reveal</button><div class="game-reveal" hidden></div></div>'}
function playRound(box,r,i,done){box.innerHTML=roundHTML(r,i);var pick=null;vals(box);box.addEventListener('input',function(){vals(box)});
  box.querySelectorAll('.gopt').forEach(function(b){b.onclick=function(){box.querySelectorAll('.gopt').forEach(function(x){x.classList.remove('sel')});b.classList.add('sel');pick=+b.dataset.j;box.querySelector('[data-go]').disabled=false}});
  box.querySelector('[data-go]').onclick=function(){var c=parseFloat(box.querySelector('[name=conf]').value)/100;var bs=brier({i:pick,c:c},r.a,r.opts.length);box.querySelectorAll('.gopt').forEach(function(x,j){x.disabled=true;if(j===r.a)x.classList.add('ok');else if(j===pick)x.classList.add('bad')});this.hidden=true;var rv=box.querySelector('.game-reveal');rv.hidden=false;rv.innerHTML='<p><b>'+(pick===r.a?'✓ Correct.':'✗ Not quite.')+'</b> '+r.reveal+' <span class="tag v">✔ verified</span></p>'+moveSVG(r.mv)+'<p class="muted"><b>Lesson:</b> '+r.lesson+'</p><p class="muted" style="font-size:13px">You said '+Math.round(c*100)+'% confident and were '+(pick===r.a?'right':'wrong')+'. Your calibration plot at the end shows whether your confidence matches your hit rate.</p>';try{var g=JSON.parse(localStorage.getItem('oe.game')||'{}');g.hist=(g.hist||[]).concat([{c:c,ok:pick===r.a}]).slice(-200);localStorage.setItem('oe.game',JSON.stringify(g))}catch(e){}if(done)done(pick===r.a,bs)}}
W.whatnext=function(el){
  var st={};try{st=JSON.parse(localStorage.getItem('oe.game')||'{}')}catch(e){}
  el.innerHTML=head('Game','What happened next?',ROUNDS.length+' real ASX & global events: market reactions and fundamental outcomes. Predict, set your confidence, then see how calibrated you are.')+'<div class="game-bar"><span id="gprog"></span><span id="gscore"></span><button class="btn ghost" id="grst">Restart</button></div><div id="gbox"></div>';
  var order=ROUNDS.map(function(_,i){return i}),idx=0,score=0,bsum=0;
  function upd(){el.querySelector('#gprog').textContent='Round '+Math.min(idx+1,ROUNDS.length)+' / '+ROUNDS.length;el.querySelector('#gscore').textContent='Correct: '+score+(idx?' · mean Brier '+(bsum/idx).toFixed(3):'')+(st.best!=null?' · best '+st.best+'/'+ROUNDS.length:'')}
  function next(){upd();var box=el.querySelector('#gbox');if(idx>=ROUNDS.length){if(st.best==null||score>st.best)st.best=score;st.lastBrier=bsum/ROUNDS.length;localStorage.setItem('oe.game',JSON.stringify(st));var g={};try{g=JSON.parse(localStorage.getItem('oe.game')||'{}')}catch(e){}box.innerHTML='<div class="game-card"><h4>Finished: '+score+' / '+ROUNDS.length+'</h4><p>Well-calibrated analysts are not always right, but when they say 70% they are right about 70% of the time. Bubbles above the dashed line mean you were <b>underconfident</b>; below it, <b>overconfident</b>.</p>'+calibSVG(g.hist||[])+'<p class="muted" style="font-size:13px">Based on your last '+((g.hist||[]).length)+' calls in this browser. For the technically minded: your mean Brier score this game was '+(bsum/ROUNDS.length).toFixed(3)+' (a uniform guess on four options scores 0.75; lower is better).</p><button class="btn" id="again">Play again</button></div>';box.querySelector('#again').onclick=start;upd();return}
    playRound(box,ROUNDS[order[idx]],idx,function(ok,bs){if(ok)score++;bsum+=bs;idx++;upd();var n=document.createElement('button');n.className='btn';n.textContent=idx>=ROUNDS.length?'See results':'Next round →';n.style.marginTop='10px';n.onclick=next;box.querySelector('.game-card').appendChild(n)})}
  function start(){idx=0;score=0;bsum=0;next()}
  el.querySelector('#grst').onclick=start;start();
};
